import React, { useState, useEffect } from 'react';
import ReactFlow, { MiniMap, Controls, Background, addEdge, useNodesState, useEdgesState } from 'reactflow';
import 'reactflow/dist/style.css';

function buildNodesEdgesForFolder(folderNode, parentId = null, posX = 0, posY = 0) {
  /**
   * Builds React Flow nodes and edges just for the provided folderNode's immediate children.
   * Positions nodes with some vertical spacing.
   */
  const nodes = [];
  const edges = [];
  if (!folderNode || !folderNode.children) return { nodes, edges };

  folderNode.children.forEach((child, idx) => {
    const id = parentId ? `${parentId}/${child.name}` : child.name;
    nodes.push({
      id,
      data: { label: child.name, nodeData: child },
      position: { x: posX + 200, y: posY + idx * 100 },
      style: {
        border: '1px solid black',
        borderRadius: 6,
        padding: 10,
        cursor: 'pointer',
        backgroundColor: child.children && child.children.length ? '#a0c4ff' : '#ffd6a5',
        fontWeight: '600',
        minWidth: 140,
        textAlign: 'center',
      }
    });
    if (parentId) {
      edges.push({ id: `${parentId}->${id}`, source: parentId, target: id, animated: true });
    }
  });

  // Also add parent folder node if parentId exists (except for root level)
  if (parentId) {
    nodes.push({
      id: parentId,
      data: { label: folderNode.name, nodeData: folderNode },
      position: { x: posX, y: posY + ((folderNode.children.length - 1) * 100) / 2 },
      style: {
        border: '2px solid #333',
        borderRadius: 8,
        padding: 12,
        fontWeight: 'bold',
        backgroundColor: '#90be6d',
        minWidth: 160,
        textAlign: 'center',
        cursor: 'pointer'
      }
    });
  }

  return { nodes, edges };
}

function findNodeById(currentNode, id, path = '') {
  if (!currentNode) return null;
  const currentId = path ? `${path}/${currentNode.name}` : currentNode.name;
  if (currentId === id) return currentNode;
  if (!currentNode.children) return null;
  for (const child of currentNode.children) {
    const found = findNodeById(child, id, currentId);
    if (found) return found;
  }
  return null;
}

export default function App() {
  const [treeData, setTreeData] = useState(null);
  const [currentFolder, setCurrentFolder] = useState(null);
  const [nodes, setNodes, onNodesChange] = useNodesState([]);
  const [edges, setEdges, onEdgesChange] = useEdgesState([]);

  // After uploading zip and receiving JSON structure
  const uploadZip = async (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const formData = new FormData();
    formData.append('repoZip', file);
    try {
      const res = await fetch('http://localhost:5000/upload', { method: 'POST', body: formData });
      if (res.ok) {
        const data = await res.json();
        setTreeData(data);
        setCurrentFolder(data);  // Start with root folder
      } else {
        alert('Failed to upload zip file');
      }
    } catch {
      alert('Error uploading file');
    }
  };

  // Whenever currentFolder updates, update nodes and edges that represent immediate children
  useEffect(() => {
    if (!currentFolder) {
      setNodes([]);
      setEdges([]);
      return;
    }
    const parentId = currentFolder.name === 'root' ? null : currentFolder.name;
    const { nodes: newNodes, edges: newEdges } = buildNodesEdgesForFolder(currentFolder, parentId);
    setNodes(newNodes);
    setEdges(newEdges);
  }, [currentFolder, setNodes, setEdges]);

  // Double click means drill down into that folder node's children (if folder)
  const onNodeDoubleClick = (event, node) => {
    if (!node.data?.nodeData) return;
    const data = node.data.nodeData;
    // If folder with children, drill down
    if (data.children && data.children.length > 0) {
      // Find full node by path id in treeData; full path id is node.id
      const folderNode = findNodeById(treeData, node.id);
      if (folderNode) {
        setCurrentFolder(folderNode);
      }
    }
  };

  const goBack = () => {
    // Go back logic: find parent folder of currentFolder by path manipulation
    if (!currentFolder || currentFolder.name === 'root') return; // already top level
    const pathParts = currentFolder.name.split('/');
    if (pathParts.length === 1) {
      setCurrentFolder(treeData); // back to root folder
    } else {
      pathParts.pop();
      const parentPath = pathParts.join('/');
      const parentNode = findNodeById(treeData, parentPath);
      if (parentNode) setCurrentFolder(parentNode);
    }
  };

  return (
    <div style={{ height: '100vh', width: '100vw', padding: 20, boxSizing: 'border-box' }}>
      <h1>Repository Folder Visualizer</h1>
      <input type="file" accept=".zip" onChange={uploadZip} />
      {currentFolder && currentFolder.name !== 'root' && (
        <button onClick={goBack} style={{ marginTop: 10, marginBottom: 10 }}>
          &larr; Back to Parent Folder
        </button>
      )}
      <div style={{ height: '80%', border: '1px solid #ccc' }}>
        <ReactFlow
          nodes={nodes}
          edges={edges}
          onNodesChange={onNodesChange}
          onEdgesChange={onEdgesChange}
          onNodeDoubleClick={onNodeDoubleClick}
          fitView
        >
          <MiniMap />
          <Controls />
          <Background />
        </ReactFlow>
      </div>
    </div>
  );
}
